#!/usr/bin/env node
// Renders the harness-specific agent files from the single source of truth:
//   skills/manual-test/roles/*.md  →  agents/*.md                    (Claude Code / plugin)
//                                  →  adapters/opencode/agents/*.md  (OpenCode)
//                                  →  adapters/codex/agents/*.toml   (OpenAI Codex)
//
// Usage: node scripts/build-agents.mjs          write the files
//        node scripts/build-agents.mjs --check  exit 1 if any generated file is stale
//
// No dependencies. Role frontmatter is flat `key: value` (name, description, tier, access).

import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const ROLES_DIR = join(ROOT, "skills", "manual-test", "roles");
const CHECK = process.argv.includes("--check");

const GENERATED = "GENERATED by scripts/build-agents.mjs from skills/manual-test/roles/ — edit the role file, then rebuild.";

// Capability tier → Claude Code model alias. `per-run` lets the orchestrator pick at dispatch time.
const CLAUDE_MODEL = { fast: "haiku", balanced: "sonnet", deep: "opus", "per-run": "inherit" };

const CLAUDE_TOOLS = {
  executor: "Read, Write, Edit, Bash, PowerShell, Glob, Grep",
  "read-only": "Read, Grep, Glob, Bash, PowerShell",
};

// OpenCode enforces these natively (last matching rule wins). Use `deny`, never `ask`, inside
// subagents: a rejected `ask` fails the whole subagent and its report is lost, while `deny` returns
// an error the model can work around. Reads (GET) stay allowed; only mutating HTTP is denied.
const MUTATING_HTTP = [
  "curl*X P*", "curl*X D*", "curl*XP*", "curl*XD*", "curl*--request*",   // -X POST, -sX POST, -XPOST
  "curl* -d*", "curl* -sd*", "curl* -sSd*", "curl*--data*",
  "curl* -F*", "curl* -sF*", "curl*--form*", "curl*--json*", "curl* -T*", "curl*--upload-file*",
  "wget*--post*", "wget*--method*", "wget*--body*",
  "http POST*", "http PUT*", "http PATCH*", "http DELETE*", "http *=*",       // HTTPie (data items imply POST)
  "xh POST*", "xh PUT*", "xh PATCH*", "xh DELETE*", "xh *=*",
  "Invoke-RestMethod*-Method P*", "Invoke-RestMethod*-Method D*",
  "Invoke-WebRequest*-Method P*", "Invoke-WebRequest*-Method D*",
];
// Tracker CLIs and git history.
const TRACKER_CLI_AND_GIT = [
  "gh issue create*", "gh issue comment*", "gh issue edit*", "gh issue close*",
  "gh pr comment*", "gh pr review*", "gh pr create*", "gh pr edit*", "gh api*",
  "glab issue create*", "glab issue note*", "glab mr note*", "glab mr create*", "glab api*",
  "git*commit*", "git*push*",
];
// Read-only reviewer: deny everything, then allow inspection commands. Anything that can write
// (redirection, chaining, subshells) is denied again at the end — last matching rule wins.
// Observed in OpenCode 1.18.31: a chain of allowed reads (`ls x && md5sum y`) still runs, because
// each subcommand is checked on its own; redirection, `tee` and `sort -o` are denied.
const REVIEWER_ALLOW = [
  "ls*", "md5sum *", "sha256sum *", "shasum *", "md5 *", "file *", "wc *", "stat *",
  "sort*", "uniq*", "cat *", "head *", "tail *", "grep *",
];
const REVIEWER_DENY_AGAIN = ["*>*", "*;*", "*&*", "*`*", "*$(*", "*<(*", "*xargs*", "*tee*", "sort*-o*"];

const OPENCODE_PERMISSION = {
  executor: [
    "permission:",
    "  edit: allow",
    "  webfetch: deny",
    "  task: deny",
    "  bash:",
    '    "*": allow',
    ...[...MUTATING_HTTP, ...TRACKER_CLI_AND_GIT].map((p) => `    "${p}": deny`),
  ],
  "read-only": [
    "permission:",
    "  edit: deny",
    "  webfetch: deny",
    "  task: deny",
    "  bash:",
    '    "*": deny',
    ...REVIEWER_ALLOW.map((p) => `    "${p}": allow`),
    ...REVIEWER_DENY_AGAIN.map((p) => `    ${JSON.stringify(p)}: deny`),
  ],
};

function parseRole(path) {
  const raw = readFileSync(path, "utf8").replace(/\r\n/g, "\n");
  const m = raw.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  if (!m) throw new Error(`${path}: missing frontmatter`);
  const meta = {};
  for (const line of m[1].split("\n")) {
    const kv = line.match(/^([A-Za-z_-]+):\s*(.*)$/);
    if (kv) meta[kv[1]] = kv[2].trim();
  }
  for (const key of ["name", "description", "tier", "access"]) {
    if (!meta[key]) throw new Error(`${path}: frontmatter needs "${key}"`);
  }
  if (!(meta.tier in CLAUDE_MODEL)) throw new Error(`${path}: unknown tier "${meta.tier}"`);
  if (!(meta.access in CLAUDE_TOOLS)) throw new Error(`${path}: unknown access "${meta.access}"`);
  return { meta, body: expandIncludes(m[2], dirname(path)) };
}

// Inline `<!-- include: rel/path.md -->` lines, demoting the included headings one level and
// dropping its H1. Lines that only point readers at the reference file are removed.
function expandIncludes(body, baseDir) {
  const out = [];
  for (const line of body.split("\n")) {
    const inc = line.match(/^<!--\s*include:\s*(.+?)\s*-->$/);
    if (inc) {
      out.push(demote(readFileSync(join(baseDir, inc[1]), "utf8").replace(/\r\n/g, "\n")).trimEnd());
    } else if (!/\(inlined in packaged agents\)/.test(line)) {
      out.push(line);
    }
  }
  return out.join("\n").replace(/\n{3,}/g, "\n\n").trim() + "\n";
}

function demote(text) {
  let inFence = false;
  const out = [];
  for (const line of text.split("\n")) {
    if (/^\s*```/.test(line)) inFence = !inFence;
    if (!inFence && /^# /.test(line)) continue;
    out.push(!inFence && /^#{2,5} /.test(line) ? `#${line}` : line);
  }
  return out.join("\n").trim();
}

const yamlString = (s) => JSON.stringify(s);

function renderClaude({ meta, body }) {
  return [
    "---",
    `name: ${meta.name}`,
    `description: ${yamlString(meta.description)}`,
    `tools: ${CLAUDE_TOOLS[meta.access]}`,
    `model: ${CLAUDE_MODEL[meta.tier]}`,
    "---",
    "",
    `<!-- ${GENERATED} -->`,
    "",
    body,
  ].join("\n");
}

function renderOpenCode({ meta, body }) {
  const modelHint = meta.tier === "deep"
    ? ["# model: <provider>/<model-id>   # optional: pin your deep-tier model; omitted = inherits the caller's"]
    : [];
  return [
    "---",
    `description: ${yamlString(meta.description)}`,
    "mode: subagent",
    ...modelHint,
    ...OPENCODE_PERMISSION[meta.access],
    "---",
    "",
    `<!-- ${GENERATED} -->`,
    "",
    body,
  ].join("\n");
}

function renderCodex({ meta, body }) {
  if (body.includes("'''")) throw new Error(`${meta.name}: body contains ''' (breaks TOML literal string)`);
  return [
    `# ${GENERATED}`,
    "# Codex subagents inherit the parent's sandbox and approvals: the \"never write to the",
    "# tracker\" rule is instruction-only here. Optionally add model / model_reasoning_effort.",
    `name = ${JSON.stringify(meta.name)}`,
    `description = ${JSON.stringify(meta.description)}`,
    `developer_instructions = '''`,
    body.trimEnd(),
    `'''`,
    "",
  ].join("\n");
}

const roles = readdirSync(ROLES_DIR).filter((f) => f.endsWith(".md")).map((f) => parseRole(join(ROLES_DIR, f)));

const outputs = roles.flatMap((role) => [
  [join(ROOT, "agents", `${role.meta.name}.md`), renderClaude(role)],
  [join(ROOT, "adapters", "opencode", "agents", `${role.meta.name}.md`), renderOpenCode(role)],
  [join(ROOT, "adapters", "codex", "agents", `${role.meta.name}.toml`), renderCodex(role)],
]);

let stale = 0;
for (const [path, content] of outputs) {
  const rel = path.slice(ROOT.length + 1).replace(/\\/g, "/");
  const current = existsSync(path) ? readFileSync(path, "utf8").replace(/\r\n/g, "\n") : null;
  if (CHECK) {
    if (current !== content) { console.error(`stale: ${rel}`); stale++; }
    continue;
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log(`${current === content ? "unchanged" : "wrote"}: ${rel}`);
}

if (CHECK) {
  if (stale) { console.error(`\n${stale} generated file(s) out of date — run: node scripts/build-agents.mjs`); process.exit(1); }
  console.log("generated agents are up to date");
}
